// Pocket sun index — record JAH-GGN-LEDFLASHLIGHT-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"lumens": 1000, "throw_m": 200, "price_usd": 40};
var value = (m.lumens*m.throw_m/m.price_usd/10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGN-LEDFLASHLIGHT-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGN-LEDFLASHLIGHT-000001|' + value.toFixed(2) + ' sun index');

